137	    @Test
138	    void blockedReturnsAllHitZoneIdsSortedAndDeduplicated() {
139	        service.createRoute(
140	                new RouteCreateRequest("r2", pts(0, 10, 100, 10), "req-" + rid("route")));
141	        // 三个相交区域 + 一个不相交区域，id 故意乱序
142	        service.createZone(zoneReq("zeta", 40, 5, 60, 15));
143	        service.createZone(zoneReq("alpha", 45, 8, 55, 12));
144	        service.createZone(zoneReq("mid", 48, 9, 52, 11));
145	        service.createZone(zoneReq("faraway", -50, -50, -40, -40));
146	
147	        MutationResponse resp = service.review(
148	                new ReviewRequest("r2", 1, 4L, "req-" + rid("review")));
149	        assertEquals(List.of("alpha", "mid", "zeta"), dataOf(resp).hitZoneIds());
150	    }
