package com.example.starter.domain;

/** 航线生命周期状态。 */
public enum RouteStatus {
    /** 待批准：新建或改航（替换）后，尚未通过审查。 */
    DRAFT,
    /** 已批准：最近一次审查通过且结论可用。 */
    APPROVED,
    /** 跑道关闭风险：新关闭窗口命中未来已批准 NORMAL 航线，只能改航、取消或转合格紧急例外。 */
    RUNWAY_RISK,
    /** 已起飞：不再受后续关闭变更影响。 */
    DEPARTED,
    /** 已取消：终态，不可再审查或起飞。 */
    CANCELLED
}

package com.example.starter.domain;

/** 航线类别：普通航线命中跑道关闭窗口即拒绝；紧急航线可按窗口例外标志附事件号通过。 */
public enum RouteCategory {
    /** 普通航线：起降时刻与任一关闭窗口相交即审查拒绝（422）。 */
    NORMAL,
    /** 紧急航线：仅在窗口允许紧急例外且附事件号时可通过。 */
    EMERGENCY
}

package com.example.starter.domain;

/** 审查原因码：随审查结果不可变保存，供审查原因查询。 */
public enum ReviewReason {
    /** 正常通过：未命中禁飞区，起降不与关闭窗口冲突且在容量内。 */
    CLEAR,
    /** 命中至少一个有效禁飞区。 */
    ZONE_HIT,
    /** 紧急例外通过：EMERGENCY 航线起降落入允许例外的关闭窗口且附事件号。 */
    EMERGENCY_EXCEPTION
}

package com.example.starter.domain;

/**
 * 航线起降计划（可空；为 null 的航线不参与跑道关闭与容量检查）。
 * 时刻均为 epoch 毫秒（UTC）。
 *
 * @param category    航线类别：NORMAL / EMERGENCY
 * @param eventNo     紧急事件号；EMERGENCY 经关闭窗口例外通过时必填，否则可为 null
 * @param depRunwayId 计划起飞跑道标识；null 表示无起飞计划
 * @param depTimeUtc  计划起飞时刻（UTC epoch 毫秒）
 * @param arrRunwayId 计划降落跑道标识；null 表示无降落计划
 * @param arrTimeUtc  计划降落时刻（UTC epoch 毫秒）
 */
public record FlightPlan(String category, String eventNo,
                         String depRunwayId, Long depTimeUtc,
                         String arrRunwayId, Long arrTimeUtc) {
}

